INSERT INTO visits (id, created_by, visit_date, location, content, status, created_at) VALUES
  ('b0000001-0000-0000-0000-000000000001', 'a0000001-0000-0000-0000-000000000002', '2026-05-15', '云南省丽江市宁蒗县希望小学', '本次探访共走访了12名受助学生家庭，了解学生的学习和生活情况。同学们本学期的学习成绩普遍有所提升，其中有3名同学进入了班级前10名。学校新的图书馆已经投入使用，孩子们非常开心。', 'published', '2026-05-15T10:00:00Z'),
  ('b0000001-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000002', '2026-04-20', '四川省凉山州昭觉县民族小学', '春季探访活动顺利完成，为同学们送去了新的校服和学习用品。学校的多媒体教室已经建成，志愿者老师们开展了为期一周的趣味课程，包括美术、音乐和科学实验。', 'published', '2026-04-20T14:30:00Z'),
  ('b0000001-0000-0000-0000-000000000003', 'a0000001-0000-0000-0000-000000000002', '2026-03-10', '贵州省黔东南州台江县施洞镇中心小学', '新学期开始，我们对20名新申请资助的学生进行了家庭走访和资格审核。经过严格的评估，最终确定了15名符合条件的受助学生。同时对在读的45名学生进行了回访，了解他们的学习进展。', 'published', '2026-03-10T09:00:00Z'),
  ('b0000001-0000-0000-0000-000000000004', 'a0000001-0000-0000-0000-000000000002', '2026-06-01', '云南省丽江市宁蒗县红旗小学', '六一儿童节特别活动，我们组织了一场趣味运动会，为孩子们送去了节日礼物。活动得到了当地教育局的大力支持，共有200多名师生参与。', 'submitted', '2026-06-01T16:00:00Z');
