  ('c0000001-0000-0000-0000-000000000003', 'b0000001-0000-0000-0000-000000000001', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E5%BF%97%E6%84%BF%E8%80%85%E8%80%81%E5%B8%88%E7%BB%99%E5%B1%B1%E5%8C%BA%E5%AD%A9%E5%AD%90%E4%B8%8A%E8%AF%BE%EF%BC%8C%E5%AD%A9%E5%AD%90%E4%BB%AC%E4%B8%93%E6%B3%A8%E5%90%AC%E8%AE%B2%E7%9A%84%E8%A1%A8%E6%83%85%EF%BC%8C%E6%B8%A9%E6%9A%96%E7%9A%84%E6%95%99%E5%AE%A4&image_size=landscape_16_9', '专注的眼神', '志愿者老师在给孩子们上课', 'approved', NULL, '2026-05-15T10:40:00Z'),
  ('c0000001-0000-0000-0000-000000000004', 'b0000001-0000-0000-0000-000000000002', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E5%B1%B1%E5%8C%BA%E5%AD%A6%E7%94%9F%E7%A9%BF%E4%B8%8A%E6%96%B0%E6%A0%A1%E6%9C%8D%EF%BC%8C%E5%BC%80%E5%BF%83%E5%9C%B0%E7%AC%91%E7%9D%80%EF%BC%8C%E8%83%8C%E6%99%AF%E6%98%AF%E9%9D%92%E5%B1%B1%E7%BB%BF%E6%A0%91&image_size=landscape_16_9', '我们的新校服', '同学们穿上了崭新的校服', 'approved', NULL, '2026-04-20T15:00:00Z'),
  ('c0000001-0000-0000-0000-000000000005', 'b0000001-0000-0000-0000-000000000002', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E5%BF%97%E6%84%BF%E8%80%85%E5%92%8C%E5%AD%A9%E5%AD%90%E4%BB%AC%E4%B8%80%E8%B5%B7%E5%81%9A%E7%A7%91%E5%AD%A6%E5%AE%9E%E9%AA%8C%EF%BC%8C%E5%AD%A9%E5%AD%90%E4%BB%AC%E5%A5%BD%E5%A5%87%E5%85%B4%E5%A5%8B%E7%9A%84%E8%A1%A8%E6%83%85&image_size=landscape_16_9', '神奇的科学课', '趣味科学实验课', 'approved', NULL, '2026-04-20T15:30:00Z'),
  ('c0000001-0000-0000-0000-000000000006', 'b0000001-0000-0000-0000-000000000003', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E5%BF%97%E6%84%BF%E8%80%85%E8%B5%B0%E8%AE%BF%E5%B1%B1%E5%8C%BA%E5%AE%B6%E5%BA%AD%EF%BC%8C%E5%92%8C%E5%AD%A6%E7%94%9F%E5%AE%B6%E9%95%BF%E4%BA%B2%E5%88%87%E4%BA%A4%E8%B0%88%EF%BC%8C%E6%9C%B4%E5%AE%9E%E7%9A%84%E5%86%9C%E5%AE%B6%E5%B0%8F%E9%99%A2&image_size=landscape_16_9', '家访的温暖', '走访受助学生家庭', 'approved', NULL, '2026-03-10T10:00:00Z'),
  ('c0000001-0000-0000-0000-000000000007', 'b0000001-0000-0000-0000-000000000004', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E5%85%AD%E4%B8%80%E5%84%BF%E7%AB%A5%E8%8A%82%E8%BF%90%E5%8A%A8%E4%BC%9A%EF%BC%8C%E5%AD%A9%E5%AD%90%E4%BB%AC%E5%9C%A8%E6%93%8D%E5%9C%BA%E4%B8%8A%E5%A5%94%E8%B7%91%EF%BC%8C%E5%BD%A9%E6%97%97%E9%A3%98%E6%89%AC%EF%BC%8C%E6%AC%A2%E4%B9%90%E7%9A%84%E6%B0%9B%E5%9B%B4&image_size=landscape_16_9', '欢乐的运动会', '六一趣味运动会', 'pending', NULL, '2026-06-01T16:30:00Z'),
