INSERT INTO recipients (id, name, age, school, grade, bio, avatar_url, created_at) VALUES
  ('d0000001-0000-0000-0000-000000000001', '小雨', 12, '宁蒗县希望小学', '六年级', '家住高寒山区，父亲常年患病，家庭收入微薄。但小雨品学兼优，是班里的学习委员，梦想成为一名医生。', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E5%8F%AF%E7%88%B1%E7%9A%84%E5%B1%B1%E5%8C%BA%E5%B0%8F%E5%A5%B3%E5%AD%A9%E5%A4%B4%E5%83%8F%EF%BC%8C%E9%9D%A2%E5%B8%A6%E5%BE%AE%E7%AC%91%EF%BC%8C%E6%B8%85%E6%BE%88%E7%9A%84%E7%9C%BC%E7%A5%9E&image_size=portrait_4_3', '2024-09-01T00:00:00Z'),
  ('d0000001-0000-0000-0000-000000000002', '小明', 14, '昭觉县民族中学', '初二', '留守儿童，与爷爷奶奶一起生活。小明数学成绩特别优秀，多次在数学竞赛中获奖。', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E9%98%B3%E5%85%89%E7%9A%84%E5%B1%B1%E5%8C%BA%E7%94%B7%E5%AD%A9%E5%A4%B4%E5%83%8F%EF%BC%8C%E9%9D%A2%E5%B8%A6%E5%BE%AE%E7%AC%91%EF%BC%8C%E6%B8%85%E6%BE%88%E7%9A%84%E7%9C%BC%E7%A5%9E&image_size=portrait_4_3', '2024-09-01T00:00:00Z'),
  ('d0000001-0000-0000-0000-000000000003', '小燕', 11, '台江县施洞镇中心小学', '五年级', '喜欢画画和唱歌，是学校文艺队的骨干。虽然家庭困难，但她总是乐观开朗，用笑容感染身边的人。', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E5%8F%AF%E7%88%B1%E7%9A%84%E8%8B%97%E6%97%8F%E5%B0%8F%E5%A5%B3%E5%AD%A9%E5%A4%B4%E5%83%8F%EF%BC%8C%E9%9D%A2%E5%B8%A6%E5%BE%AE%E7%AC%91%EF%BC%8C%E6%B8%85%E6%BE%88%E7%9A%84%E7%9C%BC%E7%A5%9E&image_size=portrait_4_3', '2024-09-01T00:00:00Z'),
  ('d0000001-0000-0000-0000-000000000004', '阿杰', 13, '宁蒗县红旗中学', '初一', '体育特长生，擅长中长跑。在今年的县运动会上获得了男子1500米冠军。', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E5%81%A5%E5%BA%B7%E7%9A%84%E5%B1%B1%E5%8C%BA%E7%94%B7%E5%AD%A9%E5%A4%B4%E5%83%8F%EF%BC%8C%E9%9D%A2%E5%B8%A6%E5%BE%AE%E7%AC%91%EF%BC%8C%E6%B8%85%E6%BE%88%E7%9A%84%E7%9C%BC%E7%A5%9E&image_size=portrait_4_3', '2025-03-01T00:00:00Z'),
  ('d0000001-0000-0000-0000-000000000005', '小芳', 10, '昭觉县城北小学', '四年级', '语文课代表，作文写得特别好。她的作文《我的梦想》获得了州级征文比赛一等奖。', 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%E6%96%87%E9%9D%99%E7%9A%84%E5%B1%B1%E5%8C%BA%E5%B0%8F%E5%A5%B3%E5%AD%A9%E5%A4%B4%E5%83%8F%EF%BC%8C%E9%9D%A2%E5%B8%A6%E5%BE%AE%E7%AC%91%EF%BC%8C%E6%B8%85%E6%BE%88%E7%9A%84%E7%9C%BC%E7%A5%9E&image_size=portrait_4_3', '2025-09-01T00:00:00Z');
INSERT INTO feedbacks (id, recipient_id, type, content, created_at) VALUES
  ('e0000001-0000-0000-0000-000000000001', 'd0000001-0000-0000-0000-000000000001', 'story', '这学期我参加了学校的数学兴趣小组，在老师的帮助下，我的数学成绩从班级第15名提升到了第3名。我特别开心！感谢资助我的叔叔阿姨，我会继续努力学习，将来也想帮助更多像我一样的小朋友。', '2026-05-20T00:00:00Z'),
  ('e0000001-0000-0000-0000-000000000002', 'd0000001-0000-0000-0000-000000000002', 'letter', '亲爱的资助人叔叔/阿姨：\n\n您好！我是小明。这学期我们学校有了新的多媒体教室，第一次上电脑课的时候，我激动得手都在抖。我终于可以在电脑上查阅学习资料了。\n\n上次您寄来的课外书我已经全部读完了，我最喜欢《十万个为什么》。等我长大了，我也要做一个有知识的人，去帮助更多需要帮助的人。\n\n谢谢您的帮助，祝您身体健康，工作顺利！\n\n此致\n敬礼\n小明\n2026年5月', '2026-05-15T00:00:00Z'),
  ('e0000001-0000-0000-0000-000000000003', 'd0000001-0000-0000-0000-000000000003', 'story', '今年的六一是我最开心的一天！志愿者老师们来学校和我们一起过节，我们做游戏、唱歌、画画。老师说我画的画特别好看，还把我的画贴在了学校的宣传栏里。我长大想当一名画家，用画笔画出美丽的家乡。', '2026-06-02T00:00:00Z'),
  ('e0000001-0000-0000-0000-000000000004', 'd0000001-0000-0000-0000-000000000004', 'grade', '本学期成绩单：\n语文：92分\n数学：95分\n英语：88分\n物理：90分\n体育：100分\n\n本学期获得荣誉：\n- 县运动会男子1500米冠军\n- 校级三好学生\n- 学习进步奖', '2026-06-10T00:00:00Z'),
  ('e0000001-0000-0000-0000-000000000005', 'd0000001-0000-0000-0000-000000000005', 'letter', '亲爱的爱心人士：\n\n您好！我是小芳。告诉您一个好消息，我的作文《我的梦想》在全州的征文比赛中获得了一等奖！当我上台领奖的时候，我心里想的是您。如果没有您的帮助，我可能连买作文选的钱都没有。\n\n我的梦想是成为一名作家，写很多很多好听的故事。我会为了这个梦想努力的！\n\n再次感谢您的帮助！\n\n小芳\n2026年5月', '2026-05-25T00:00:00Z');
