INSERT INTO exception_records (id, type, title, status, impact_scope, handling_path, review_notes, close_reason, parent_exception_id, created_at, updated_at) VALUES
  ('i0000001-0000-0000-0000-000000000001', 'material_discrepancy', '4月学习物资采购数量差异', 'closed', '涉及昭觉县200名学生的校服发放，实际到货195套，缺少5套。影响5名学生未能及时领取校服。', '1. 立即联系供应商核实发货数量\n2. 对已发放物资进行清点登记\n3. 协调供应商补发缺失的5套校服\n4. 对受影响的5名学生进行登记，待补发后优先发放', '供应商承认是仓库盘点错误导致少发，已于5月5日补发到位。已建立物资入库双人清点制度，防止类似问题再次发生。同时修订了采购合同，增加了延期交付的赔偿条款。', '供应商已补发缺失物资，问题已解决。已优化物资入库流程，建立双人清点和签字确认制度。', NULL, '2026-04-26T09:00:00Z', '2026-05-10T10:00:00Z'),
  ('i0000001-0000-0000-0000-000000000002', 'budget_overrun', '3月探访经费报销金额差异', 'closed', '贵州探访经费报销中，有一笔1200元的住宿费用票据与实际消费不符，涉及探访经费预算。影响金额1200元。', '1. 核对报销票据与消费流水\n2. 联系酒店核实消费明细\n3. 要求经办人说明情况\n4. 退回多报金额，完善财务审核流程', '经查为经办人误将私人消费混入报销，已进行批评教育，多报金额已退回。已加强财务审核，实行双人签字制度。所有支出超过5000元需财务负责人复核。', '问题已查清，多报款项1200元已全额追回，相关人员已进行批评教育。财务审核流程已优化，增加双人复核环节。', NULL, '2026-03-15T10:00:00Z', '2026-03-25T16:00:00Z'),
  ('i0000001-0000-0000-0000-000000000003', 'material_discrepancy', '六一活动礼品数量不符', 'handling', '六一儿童节活动准备的200份礼品，实际发放时发现缺少12份，影响12名学生未能当场领取礼品。涉及价值约1800元。', '1. 立即清点库存确认缺失数量\n2. 紧急采购补充缺失礼品\n3. 对未领到礼品的学生进行登记\n4. 启动二次补发，安排志愿者上门送礼品', NULL, NULL, NULL, '2026-06-02T08:00:00Z', '2026-06-03T10:00:00Z'),
  ('i0000001-0000-0000-0000-000000000004', 'other', '受助学生资格复核发现问题', 'investigating', '在春季学期资格复核中，发现1名受助学生的家庭经济状况已明显改善（父母外出务工收入稳定），不再符合资助条件。涉及助学金名额1个。', '1. 再次核实该学生家庭实际情况（收入证明、走访邻里）\n2. 与学校老师沟通了解学生在校表现\n3. 与学生家长进行面谈，说明政策调整\n4. 研究调整资助资格，将名额转给其他需要帮助的学生\n5. 做好学生心理疏导工作', NULL, NULL, NULL, '2026-06-08T14:00:00Z', '2026-06-08T14:00:00Z');
