  ('j0000001-0000-0000-0000-000000000003', 'i0000001-0000-0000-0000-000000000001', 'handling', '联系供应商：供应商承认少发，承诺5月5日前补发', 'a0000001-0000-0000-0000-000000000002', '2026-04-27T10:00:00Z'),
  ('j0000001-0000-0000-0000-000000000004', 'i0000001-0000-0000-0000-000000000001', 'handling', '物资补发到位：5套校服已收到并发放给学生', 'a0000001-0000-0000-0000-000000000002', '2026-05-05T15:00:00Z'),
  ('j0000001-0000-0000-0000-000000000005', 'i0000001-0000-0000-0000-000000000001', 'note', '复盘总结：已建立物资入库双人清点制度，增加采购合同赔偿条款', 'a0000001-0000-0000-0000-000000000001', '2026-05-08T14:00:00Z'),
  ('j0000001-0000-0000-0000-000000000006', 'i0000001-0000-0000-0000-000000000003', 'status_change', '创建异常记录：六一礼品缺少12份', 'a0000001-0000-0000-0000-000000000002', '2026-06-02T08:00:00Z'),
  ('j0000001-0000-0000-0000-000000000007', 'i0000001-0000-0000-0000-000000000003', 'status_change', '分配处理：请尽快采购补充，确保每个孩子都能拿到礼物', 'a0000001-0000-0000-0000-000000000001', '2026-06-02T08:30:00Z');
